Here's a simple function in C++ that uses the `pugixml` library to convert markdown text to HTML. Please note that you will need to install the `pugixml` library and include it in your project for this code to work.

```cpp
#include <pugixml.hpp>
#include <string>

std::string markdown_to_html(const std::string& markdown_text) {
    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_string(markdown_text.c_str());

    if (!result) {
        // Handle parsing error
        return "";
    }

    std::string html;
    doc.save(html);

    // Remove XML declaration
    size_t pos = html.find("<html>");
    if (pos!= std::string::npos) {
        html = html.substr(pos + 6); // 6 is the length of "<html>"
    }

    // Remove XML closing tag
    pos = html.find("</html>");
    if (pos!= std::string::npos) {
        html = html.substr(0, pos);
    }

    return html;
}
```

