**Word Counter Program in C++**
================================

This program reads a text file line by line and counts the number of occurrences of a specific word in the file.

**word_counter.cpp**
```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <map>

// Function to count the occurrences of a word in a file
int countWordOccurrences(const std::string& filename, const std::string& word) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error: Unable to open file " << filename << std::endl;
        return -1;
    }

    std::map<std::string, int> wordCount;
    std::string line;
    std::string currentWord;

    while (std::getline(file, line)) {
        std::istringstream iss(line);
        while (iss >> currentWord) {
            // Convert to lowercase for case-insensitive comparison
            for (char& c : currentWord) {
                c = std::tolower(c);
            }
            // Count the occurrences of the word
            ++wordCount[currentWord];
        }
    }

    file.close();

    // Find the count of the specific word
